package abmeter

import (
	"encoding/json"
	"os"
	"testing"
)

// The parity fixture locks the cross-SDK bucketing contract: 1000
// [salt, user_id, expected] triples generated by the Ruby oracle
// (abmeter-sdk/bin/generate_num_utils_parity_fixture.rb). Every SDK must
// reproduce every row bit-for-bit.
func TestToPercentageParity(t *testing.T) {
	raw, err := os.ReadFile("testdata/num_utils_parity.json")
	if err != nil {
		t.Fatalf("reading parity fixture: %v", err)
	}
	var rows [][3]any
	if err := json.Unmarshal(raw, &rows); err != nil {
		t.Fatalf("parsing parity fixture: %v", err)
	}
	if len(rows) != 1000 {
		t.Fatalf("expected 1000 fixture rows, got %d", len(rows))
	}
	for _, row := range rows {
		salt := row[0].(string)
		userID := row[1].(string)
		expected := int(row[2].(float64))
		if got := toPercentage(salt, userID); got != expected {
			t.Fatalf("toPercentage(%q, %q) = %d, want %d", salt, userID, got, expected)
		}
	}
}

func TestToPercentageRange(t *testing.T) {
	for i := 0; i < 1000; i++ {
		p := toPercentage("salt", string(rune('a'+i%26))+string(rune('0'+i%10)))
		if p < 1 || p > 100 {
			t.Fatalf("percentage %d out of 1..100", p)
		}
	}
}
